srun --jobid=1009495 --overlap --nodes=1 --ntasks=1 --cpus-per-task=1 --gres=none --time=00:01:00 python3 -c import os,json,pathlib,sys
roots=json.load(sys.stdin)
needles=roots+[pathlib.Path(x).name for x in roots if pathlib.Path(x).name not in ['interrupted_attempts']]
matches=[]; scientific=[]; count=0
for p in pathlib.Path('/proc').iterdir():
 if not p.name.isdigit():continue
 try:
  if p.stat().st_uid!=os.getuid() or int(p.name)==os.getpid():continue
  count+=1
  cmd=(p/'cmdline').read_bytes().replace(b'\0',b' ').decode(errors='replace')
  cwd=os.readlink(p/'cwd')
  links=[]
  for fd in (p/'fd').iterdir():
   try:links.append(os.readlink(fd))
   except FileNotFoundError:pass
  values=[cwd]+links
  if any(any(n in v for n in needles) for v in values) or (not cmd.startswith('python -c') and any(n in cmd for n in needles)):
   matches.append(dict(pid=p.name,cwd=cwd,cmd=cmd,matching_links=[v for v in values if any(n in v for n in needles)]))
  if any(s in cmd for s in ['run_lammps','lmp ','memory_sources','bcr','alignment','distance_encoder']):
   if not cmd.startswith('python -c'):scientific.append(dict(pid=p.name,cwd=cwd,cmd=cmd))
 except (FileNotFoundError,ProcessLookupError,PermissionError):continue
print(json.dumps(dict(process_count=count,matches=matches,scientific=scientific)))

